const raw = ($json.stdout || '').trim();
let h;
try {
  h = JSON.parse(raw);
} catch (e) {
  return [{json: {status: "DEGRADED", repair_needed: true, severity: "critical", issues: ["Health output was not valid JSON"], raw}}];
}

const issues = [];
if (h.controller_reachable !== "ok") issues.push("hpc-controller unreachable");
if (h.compute_reachable !== "ok") issues.push("hpc-compute01 unreachable");
if (h.slurmctld !== "active") issues.push("slurmctld inactive");
if (h.controller_munge !== "active") issues.push("controller Munge inactive");
if (h.slurmd !== "active") issues.push("slurmd inactive");
if (h.compute_munge !== "active") issues.push("compute Munge inactive");
if (h.slurm_controller !== "up") issues.push("Slurm controller not responding");
if (!["idle","alloc","mixed","mix"].includes((h.slurm_state || "").toLowerCase())) issues.push(`Slurm node state: ${h.slurm_state}`);
if (h.nfs_compute !== "mounted") issues.push("NFS /research not mounted on compute node");
if (Number(h.research_disk_pct || 0) >= 85) issues.push(`Research disk usage high: ${h.research_disk_pct}%`);
if (h.prom_controller !== "200") issues.push("Controller Node Exporter unavailable");
if (h.prom_compute !== "200") issues.push("Compute Node Exporter unavailable");
if (h.prometheus !== "200") issues.push("Prometheus unhealthy");
if (!["200","302"].includes(h.grafana)) issues.push("Grafana unavailable");

let severity = "info";
if (issues.length) severity = Number(h.research_disk_pct || 0) >= 95 || h.controller_reachable !== "ok" || h.compute_reachable !== "ok" ? "critical" : "warning";

return [{
  json: {
    ...h,
    status: issues.length ? "DEGRADED" : "HEALTHY",
    repair_needed: issues.length > 0,
    severity,
    issues,
    checked_at: new Date().toISOString()
  }
}];

const before = $('Analyze Health').first().json;
const raw = ($json.stdout || '').trim();

let after;
try {
  after = JSON.parse(raw);
} catch (e) {
  after = {parse_error: true, raw};
}

const issues = [];
if (after.controller_reachable !== "ok") issues.push("hpc-controller unreachable");
if (after.compute_reachable !== "ok") issues.push("hpc-compute01 unreachable");
if (after.slurmctld !== "active") issues.push("slurmctld inactive");
if (after.controller_munge !== "active") issues.push("controller Munge inactive");
if (after.slurmd !== "active") issues.push("slurmd inactive");
if (after.compute_munge !== "active") issues.push("compute Munge inactive");
if (after.slurm_controller !== "up") issues.push("Slurm controller not responding");
if (!["idle","alloc","mixed","mix"].includes((after.slurm_state || "").toLowerCase())) issues.push(`Slurm node state: ${after.slurm_state}`);
if (after.nfs_compute !== "mounted") issues.push("NFS /research not mounted");
if (Number(after.research_disk_pct || 0) >= 85) issues.push(`Research disk usage high: ${after.research_disk_pct}%`);
if (after.prom_controller !== "200") issues.push("Controller Node Exporter unavailable");
if (after.prom_compute !== "200") issues.push("Compute Node Exporter unavailable");
if (after.prometheus !== "200") issues.push("Prometheus unhealthy");
if (!["200","302"].includes(after.grafana)) issues.push("Grafana unavailable");

let finalStatus = "HEALTHY";
if (issues.length) finalStatus = "DEGRADED";
else if (before.status === "DEGRADED") finalStatus = "RECOVERED";

const report = {
  workflow: "HPC Autopilot",
  final_status: finalStatus,
  initial_status: before.status,
  auto_heal_attempted: before.repair_needed,
  initial_issues: before.issues || [],
  remaining_issues: issues,
  node_state: after.slurm_state,
  research_disk_pct: Number(after.research_disk_pct || 0),
  checked_at: new Date().toISOString()
};

const line = `[${report.checked_at}] status=${report.final_status} initial=${report.initial_status} node=${report.node_state} disk=${report.research_disk_pct}% issues="${report.remaining_issues.join('; ')}"\n`;

return [{json: {...report, log_b64: Buffer.from(line).toString('base64')}}];
